for api in total_api:
    print(f"{api}: {len(total_api[api])}개")
    os.makedirs(f"api/{api}_api", exist_ok=True)

    for idx,val in enumerate(total_api[api]):
        print(f"{api}: {idx} / {len(total_api[api])}개")
        url = f"https://maplestoryworlds-creators.nexon.com/ko/apiReference/{api}/{val}"
        driver.get(url)

        time.sleep(3)  # 페이지 로딩 및 자바스크립트 실행 대기

        html = driver.page_source
        soup = BeautifulSoup(html, "html.parser")
        content_div = soup.find_all('code', attrs={'data-language': 'lua'})

        # 텍스트 파일로 저장
        with open(f'api/{api}_api/{val}.txt', 'w', encoding='utf-8') as f:
            for code in content_div:
                f.write(code.get_text())  
driver.quit()